internal fun bounds(period:String):Pair<String,String>{val d=LocalDate.parse(dayKey());val first=when(period){"semaine"->d.minusDays((d.dayOfWeek.value-1).toLong());"mois"->d.withDayOfMonth(1);"annee"->d.withDayOfYear(1);else->d};return first.toString() to d.toString()}
@Composable internal fun ConnectedGrillad(appearance:String,onAppearance:(String)->Unit){
 val api=remember{ConnectedApi(BuildConfig.GRILLAD_API_URL,BuildConfig.GRILLAD_PUBLIC_KEY)}
 val scope=rememberCoroutineScope();val context=LocalContext.current;val installation=remember{val prefs=context.getSharedPreferences("grillad-installation-v1",0);prefs.getString("id",null)?.takeIf{runCatching{UUID.fromString(it)}.isSuccess}?:UUID.randomUUID().toString().also{check(prefs.edit().putString("id",it).commit())}}
 var session by remember{mutableStateOf<JSONObject?>(null)};var site by remember{mutableStateOf<JSONObject?>(null)};var data by remember{mutableStateOf<JSONObject?>(null)}
 var pending by remember{mutableStateOf<JSONObject?>(null)};var busy by remember{mutableStateOf(false)};var msg by remember{mutableStateOf("")}
 var pushRegistered by remember{mutableStateOf(false)}
 var phone by remember{mutableStateOf("")};var password by remember{mutableStateOf("")}
 var page by remember{mutableStateOf("Accueil")};var period by remember{mutableStateOf("jour")}
 var name by remember(page,site){mutableStateOf("")};var amount by remember(page,site){mutableStateOf("")};var cost by remember(page,site){mutableStateOf("")};var selected by remember(page,site){mutableStateOf("")};var family by remember(page){mutableStateOf(families.first())};var reason by remember(page,site){mutableStateOf("")}
 fun reset(){GrilladPush.setOptIn(context,false);pushRegistered=false;session=null;site=null;data=null;pending=null;password="";page="Accueil"}
 suspend fun call(body:JSONObject):Any{val s=session;return try{api.call(body,s?.optString("access"))}catch(e:GrilladApiError){if(e.status!=401||s==null||body.optString("action") in listOf("login","refresh","logout"))throw e;val next=api.call(obj("action" to "refresh","refresh" to s.optString("refresh"))) as JSONObject;session=next;api.call(body,next.optString("access"))}}
 fun run(action:suspend ()->Unit){if(busy)return;busy=true;msg="";scope.launch{try{action()}catch(e:kotlinx.coroutines.CancellationException){throw e}catch(e:Exception){msg=e.message?:"Opération refusée";if(e is GrilladApiError&&e.status in listOf(401,403)){data=null;if(e.status==401)reset()}}finally{busy=false}}}
 suspend fun load(s:JSONObject,p:String=period){data=null;val (from,to)=bounds(p);val snapshot=call(obj("action" to "snapshot","org" to s.optString("org"),"site" to s.optString("site"),"from" to from,"to" to to)) as JSONObject;val attendance=try{call(obj("action" to "attendance_status","org" to s.optString("org"),"site" to s.optString("site"))) as JSONObject}catch(e:GrilladApiError){if(e.status in listOf(401,403))throw e;null};snapshot.put("attendance",attendance?:JSONObject.NULL);try{snapshot.put("inbox",call(obj("action" to "notice_feed","org" to s.optString("org"),"site" to s.optString("site"))));if(s.optString("role")!="seller"){snapshot.put("daily",call(obj("action" to "daily_list","org" to s.optString("org"),"site" to s.optString("site"))));snapshot.put("connect",call(obj("action" to "connect_list","org" to s.optString("org"),"site" to s.optString("site"))));snapshot.put("pilotage",call(obj("action" to "pilotage_status","org" to s.optString("org"),"site" to s.optString("site"))));snapshot.put("security",call(obj("action" to "security_list","org" to s.optString("org"),"site" to s.optString("site"))));snapshot.put("prediction",call(obj("action" to "prediction","org" to s.optString("org"),"site" to s.optString("site"))))}}catch(e:GrilladApiError){if(e.status in listOf(401,403))throw e};data=snapshot}
 suspend fun submit(req:JSONObject){pending=req;try{call(req);pending=null;msg="Opération confirmée par le serveur";site?.let{load(it)}}catch(e:GrilladApiError){if(e.status in listOf(400,401,403))pending=null;throw e}}
 fun mutate(operation:String,payload:JSONObject){val s=site?:return;if(pending!=null){msg="Vérifier la requête en attente";return};run{submit(obj("action" to "mutate","org" to s.optString("org"),"site" to s.optString("site"),"event" to UUID.randomUUID().toString(),"operation" to operation,"payload" to payload))}}
 fun registerPush(){val s=site?:return;run{val token=GrilladPush.token(context);val p=call(obj("action" to "push_register","org" to s.optString("org"),"site" to s.optString("site"),"token" to token,"project" to BuildConfig.GRILLAD_FIREBASE_PROJECT,"enabled" to true)) as JSONObject;pushRegistered=p.optBoolean("registered");GrilladPush.setOptIn(context,pushRegistered);msg=if(pushRegistered)"Appareil inscrit. Livraison distante non qualifiée." else "Inscription refusée"}}
 val pushPermission=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){granted->if(granted)registerPush()else msg="Permission de notification refusée"}
 if(!validGrilladConfig(BuildConfig.GRILLAD_API_URL,BuildConfig.GRILLAD_PUBLIC_KEY)){Text("Configuration GRILLAD invalide. Aucun accès.");return}
 if(session==null){Column(Modifier.fillMaxSize().padding(24.dp).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(14.dp)){Text("GrillaD",style=MaterialTheme.typography.headlineLarge);Text("Connexion professionnelle");OutlinedTextField(phone,{phone=it},label={Text("Téléphone (+237…)")},modifier=Modifier.fillMaxWidth());OutlinedTextField(password,{password=it},label={Text("Mot de passe")},visualTransformation=PasswordVisualTransformation(),modifier=Modifier.fillMaxWidth());Button({run{val s=api.call(obj("action" to "login","phone" to phone,"password" to password,"installation" to installation,"platform" to "android")) as JSONObject;password="";val first=rows(s.optJSONArray("sites")).firstOrNull()?:error("Aucun point autorisé");session=s;site=first;load(first)}},enabled=!busy,modifier=Modifier.fillMaxWidth().heightIn(min=52.dp)){Text("Se connecter")};TextButton({run{api.call(obj("action" to "recovery","phone" to phone));msg="Demande transmise au support"}},enabled=!busy){Text("Mot de passe oublié")};if(msg.isNotBlank())Text(msg)};return}
 val manager=site?.optString("role")!="seller";val groups=if(manager)linkedMapOf("Accueil" to listOf("Accueil"),"Vente" to listOf("Ventes","Préparations","Catalogue"),"Activité" to listOf("Caisse","Dépenses","Rapports","Prévisions","Point journalier"),"Plus" to listOf("Équipe","Notifications","Vidéosurveillance","ZIPPLE Connect","Abonnement","Profil"))else linkedMapOf("Accueil" to listOf("Accueil"),"Vente" to listOf("Ventes","Préparations"),"Plus" to listOf("Équipe","Notifications","Profil"))
 val group=groups.entries.firstOrNull{page in it.value}?.key?:"Accueil"
 Scaffold(bottomBar={NavigationBar{groups.forEach{(g,p)->NavigationBarItem(selected=group==g,onClick={page=p.first()},enabled=!busy,icon={Text(g.take(1))},label={Text(g)})}}}){insets->
 Column(Modifier.fillMaxSize().padding(insets).padding(16.dp),verticalArrangement=Arrangement.spacedBy(8.dp)){
  Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text("GrillaD",style=MaterialTheme.typography.headlineMedium);TextButton({run{try{api.call(obj("action" to "logout"),session?.optString("access"))}finally{reset()}}},enabled=!busy&&pending==null){Text("Déconnexion")}}
  Row(Modifier.horizontalScroll(rememberScrollState())){rows(session?.optJSONArray("sites")).forEach{s->OutlinedButton({if(pending==null)run{site=s;page="Accueil";load(s)}},enabled=!busy&&pending==null){Text((if(s.optString("site")==site?.optString("site"))"✓ " else "")+s.optString("name"))}}}
  if(group!="Accueil")Row(Modifier.horizontalScroll(rememberScrollState())){groups.getValue(group).forEach{p->TextButton({page=p},enabled=!busy){Text(p)}}}
  Text(page,style=MaterialTheme.typography.headlineSmall);if(msg.isNotBlank())Text(msg)
  if(pending!=null){Text("Confirmation incertaine — aucune nouvelle opération.");Button({val req=pending; if(req!=null)run{submit(req)}},enabled=!busy){Text("Vérifier la même requête")}}
  TextButton({site?.let{s->run{load(s)}}},enabled=!busy&&pending==null){Text("Actualiser")}
  val d=data;val enabled=!busy&&pending==null&&d!=null
  if(d==null){Text("Pas de données confirmées.");return@Column}
  val items=rows(d.optJSONArray("items"));val f=d.optJSONObject("finance");val cash=d.optJSONObject("cash")
  Column(Modifier.weight(1f).verticalScroll(rememberScrollState()),verticalArrangement=Arrangement.spacedBy(12.dp)){
   Text("Actualisé : "+d.optString("generated_at"),style=MaterialTheme.typography.bodySmall)
   when(page){
    "Accueil","Rapports","Point journalier"->{if(f!=null){GrilladHero(f.optLong("ca"),d.optLong("target"));GrilladMetric("Ventes",f.optString("sales_count"),Modifier.fillMaxWidth());GrilladMetric("Dépenses",f.optString("charges")+" F",Modifier.fillMaxWidth());GrilladMetric("Résultat indicatif",if(f.isNull("cost"))"Non calculable" else (f.optLong("ca")-f.optLong("cost")-f.optLong("charges")).toString()+" F",Modifier.fillMaxWidth())};if(page=="Rapports")Row(Modifier.horizontalScroll(rememberScrollState())){listOf("jour","semaine","mois","annee").forEach{p->TextButton({period=p;site?.let{s->run{load(s,p)}}},enabled=enabled){Text(if(period==p)"✓ "+p else p)}}};if(page=="Rapports")GrilladReportFilters(site,d,period,enabled){filters->val s=site;if(s!=null)call(filters.put("action","report").put("org",s.optString("org")).put("site",s.optString("site"))) as JSONObject else error("Aucun point")};if(page=="Accueil"){Button({page="Ventes"},enabled=enabled,modifier=Modifier.fillMaxWidth().heightIn(min=52.dp)){Text("Nouvelle vente")};if(manager){OutlinedTextField(amount,{amount=it},label={Text("Objectif CA FCFA")});Button({mutate("target",obj("day" to dayKey(),"amount" to amount.toLongOrNull()))},enabled=enabled){Text("Enregistrer l’objectif")}}};if(page=="Point journalier"){Text("Services clôturés — données serveur uniquement");rows(d.optJSONArray("daily")).forEach{x->val summary=x.optJSONObject("data");OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text(x.optString("service_day")+" · version "+x.optString("version"));Text("CA "+(summary?.optString("ca")?:"—")+" F · dépenses "+(summary?.optString("expenses")?:"—")+" F");Text(x.optString("starts_at")+" → "+x.optString("ends_at"))}}};if(rows(d.optJSONArray("daily")).isEmpty())Text("Aucune synthèse disponible.")}}
    "Catalogue"->{OutlinedTextField(name,{name=it},label={Text("Nom de l’article")});Row(Modifier.horizontalScroll(rememberScrollState())){families.forEach{v->TextButton({family=v}){Text(if(family==v)"✓ "+v else v)}}};OutlinedTextField(amount,{amount=it},label={Text("Prix")});OutlinedTextField(cost,{cost=it},label={Text("Coût facultatif")});Button({mutate("add_item",obj("name" to name,"family" to family,"price" to amount.toLongOrNull(),"cost" to cost.toLongOrNull()))},enabled=enabled){Text("Ajouter l’article")};items.forEach{x->OutlinedButton({selected=x.optString("id")}){Text((if(selected==x.optString("id"))"✓ " else "")+x.optString("name")+" · "+x.optString("price")+" F")}};if(selected.isNotBlank()){OutlinedTextField(reason,{reason=it},label={Text("Motif de changement du prix")});Button({mutate("change_price",obj("item" to selected,"price" to amount.toLongOrNull(),"reason" to reason))},enabled=enabled){Text("Modifier le prix sélectionné")}}}
    "Ventes","Préparations"->{items.forEach{x->OutlinedButton({selected=x.optString("id")},modifier=Modifier.fillMaxWidth()){Text((if(selected==x.optString("id"))"✓ " else "")+x.optString("name")+" · "+x.optString("remaining")+" disponibles")}};OutlinedTextField(amount,{amount=it},label={Text("Quantité")});Button({mutate(if(page=="Ventes")"sell" else "prepare",obj("item" to selected,"qty" to amount.toLongOrNull()))},enabled=enabled&&selected.isNotBlank()){Text(if(page=="Ventes")"Enregistrer la vente" else "Enregistrer la préparation")};if(page=="Ventes"){if(manager)OutlinedTextField(reason,{reason=it},label={Text("Motif d’annulation")});rows(d.optJSONArray("sales")).forEach{x->OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text(x.optString("qty")+" unités · "+x.optString("total")+" F");if(x.optBoolean("cancelled"))Text("Annulée")else if(manager&&cash!=null)TextButton({mutate("cancel_sale",obj("sale" to x.optString("id"),"reason" to reason))},enabled=enabled){Text("Annuler cette vente")}}}}}}
    "Caisse"->{if(cash!=null){GrilladMetric("Attendu",cash.optString("expected")+" F");OutlinedTextField(reason,{reason=it},label={Text("Justification si écart")})};OutlinedTextField(amount,{amount=it},label={Text(if(cash==null)"Fonds initial" else "Montant compté")});Button({mutate(if(cash==null)"open_cash" else "close_cash",if(cash==null)obj("opening" to amount.toLongOrNull())else obj("counted" to amount.toLongOrNull(),"reason" to reason))},enabled=enabled){Text(if(cash==null)"Ouvrir la caisse" else "Clôturer")}}
    "Dépenses"->{OutlinedTextField(name,{name=it},label={Text("Libellé")});OutlinedTextField(amount,{amount=it},label={Text("Montant")});Button({mutate("expense",obj("label" to name,"value" to amount.toLongOrNull()))},enabled=enabled){Text("Enregistrer")};rows(d.optJSONArray("expenses")).forEach{x->Text(x.optString("label")+" · "+x.optString("value")+" F")}}
    "Prévisions"->{val prediction=d.optJSONObject("prediction");GrilladMetric("CA estimé au prochain service",if(prediction==null||prediction.isNull("ca_estimate"))"Données insuffisantes" else prediction.optString("ca_estimate")+" F");Text("Estimation sur services clôturés, non garantie.");rows(prediction?.optJSONArray("items")).forEach{x->OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text(x.optString("name"));Text(if(x.isNull("quantity"))"Historique insuffisant" else x.optString("quantity")+" unités estimées · "+x.optString("ca_estimate")+" F");Text(x.optString("observed_days")+" services observés · "+x.optString("possible_shortages")+" ruptures possibles");if(!x.isNull("quantity"))Text("Restant "+x.optString("remaining")+" · préparation supplémentaire indicative "+x.optString("additional_preparation"))}}}}
    "Notifications"->{val inbox=d.optJSONObject("inbox");rows(inbox?.optJSONArray("items")).forEach{x->OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text(x.optString("text"));Text(if(x.optBoolean("read"))"Lu" else "Non lu");if(!x.optBoolean("read"))TextButton({site?.let{s->run{call(obj("action" to "notice_ack","org" to s.optString("org"),"site" to s.optString("site"),"id" to x.optString("id")));load(s)}}},enabled=enabled){Text("Marquer comme lu")}}}};Text("Préférences");listOf("sales" to "Ventes","stock" to "Stocks","cash" to "Caisse","daily" to "Point journalier","attendance" to "Pointage","connect" to "Connect","security" to "Sécurité").forEach{(category,label)->Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(label);Switch(checked=inbox?.optJSONObject("preferences")?.optBoolean(category,true)?:true,onCheckedChange={value->site?.let{s->run{call(obj("action" to "notice_set","org" to s.optString("org"),"site" to s.optString("site"),"category" to category,"enabled" to value));load(s)}}},enabled=enabled)}};Text(if(pushRegistered)"Appareil inscrit — livraison distante non qualifiée." else "Notifications distantes non inscrites.");OutlinedButton({if(Build.VERSION.SDK_INT>=33&&context.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)pushPermission.launch(Manifest.permission.POST_NOTIFICATIONS)else registerPush()},enabled=enabled){Text("Inscrire cet appareil")};OutlinedButton({val s=site;if(s!=null)run{GrilladPush.setOptIn(context,false);pushRegistered=false;call(obj("action" to "push_register","org" to s.optString("org"),"site" to s.optString("site"),"enabled" to false));GrilladPush.delete(context);msg="Notifications distantes désactivées"}},enabled=enabled){Text("Désactiver les notifications distantes")}}
    "Équipe"->{GrilladAttendance(d.optJSONObject("attendance"),enabled){proof->val s=site;if(s!=null&&pending==null)run{proof.put("action","attendance_capture").put("org",s.optString("org")).put("site",s.optString("site")).put("event",UUID.randomUUID().toString());submit(proof)}}}
    "Vidéosurveillance"->{val sec=d.optJSONObject("security");Text(if(sec?.optBoolean("available")==true)"Site lié à NAXA SECURITY." else "Aucune liaison autorisée.");Text("Direct indisponible — passerelle non qualifiée.");rows(sec?.optJSONArray("cameras")).forEach{x->OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text(x.optString("name"));Text(when(x.optString("status")){"online"->"En ligne";"offline"->"Hors ligne";else->"État inconnu"});Text(x.optString("observed_at"))}}};Text("Incidents");rows(sec?.optJSONArray("incidents")).forEach{x->Text(x.optString("category")+" · "+x.optString("observed_at"))}}
    "ZIPPLE Connect"->{val connect=d.optJSONObject("connect");Text(if(connect?.optBoolean("available")==true)"Lien partenaire actif dans le serveur candidat." else "Aucun partenaire actif.");Text("Commandes et paiements GRILLAD séparés.");OutlinedTextField(amount,{amount=it},label={Text("Montant espèces reçu")});OutlinedTextField(reason,{reason=it},label={Text("Motif si refus/annulation")});rows(connect?.optJSONArray("orders")).forEach{o->OutlinedCard(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){Text(o.optString("id").take(8)+" · "+o.optString("status")+" · "+o.optString("total")+" F");rows(o.optJSONArray("lines")).forEach{l->Text(l.optString("name")+" × "+l.optString("qty"))};val next=when(o.optString("status")){"submitted"->listOf("accepted","refused");"accepted"->listOf("preparing","cancelled");"preparing"->listOf("ready","cancelled");"ready"->listOf("handed","cancelled");else->emptyList()};next.forEach{n->TextButton({val s=site;if(s!=null)run{submit(obj("action" to "connect_transition","org" to s.optString("org"),"site" to s.optString("site"),"order" to o.optString("id"),"event" to UUID.randomUUID().toString(),"next" to n,"received" to amount.toLongOrNull(),"reason" to reason))}},enabled=enabled){Text(n)}}}}}}
    "Abonnement"->Text("ACCÈS : 2 000 F/mois ou 24 000 F/an. PREMIUM : 6 000 F/mois ou 60 000 F/an.")
    "Profil"->listOf("Système","Clair","Sombre").forEach{m->OutlinedButton({onAppearance(m)}){Text(if(appearance==m)"✓ "+m else m)}}
   }
  }
